public class DOMNodePointer_findEnclosingAttribute_TriageGen0Test {

    /**
     * Helper method to access the protected static method via reflection.
     */
    @SuppressWarnings("unchecked")
    private String invokeFindEnclosingAttribute(Node n, String attrName) throws Exception {
        Method method = DOMNodePointer.class.getDeclaredMethod("findEnclosingAttribute", Node.class, String.class);
        method.setAccessible(true);
        return (String) method.invoke(null, n, attrName);
    }

    @Test
    public void testFindEnclosingAttribute_NullNode() throws Exception {
        assertNull(invokeFindEnclosingAttribute(null, "testAttr"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeFoundOnCurrentNode() throws Exception {
        Element element = mock(Element.class);
        when(element.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(element.getAttribute("target")).thenReturn("value1");

        assertEquals("value1", invokeFindEnclosingAttribute(element, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeFoundOnParentNode() throws Exception {
        // Parent Element
        Element parent = mock(Element.class);
        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("target")).thenReturn("parentValue");

        // Child Element (no attribute)
        Element child = mock(Element.class);
        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getAttribute("target")).thenReturn(""); // Empty string case
        when(child.getParentNode()).thenReturn(parent);

        assertEquals("parentValue", invokeFindEnclosingAttribute(child, "target"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeIsNotNullButEmpty() throws Exception {
        // Child has empty attribute, parent has valid attribute
        Element parent = mock(Element.class);
        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("test")).thenReturn("found");

        Element child = mock(Element.class);
        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getAttribute("test")).thenReturn(""); 
        when(child.getParentNode()).thenReturn(parent);

        assertEquals("found", invokeFindEnclosingAttribute(child, "test"));
    }

    @Test
    public void testFindEnclosingAttribute_AttributeIsNull() throws Exception {
        Element parent = mock(Element.class);
        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("test")).thenReturn(null);

        Element child = mock(Element.class);
        when(child.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(child.getAttribute("test")).thenReturn(null);
        when(child.getParentNode()).thenReturn(parent);

        // Should continue to parent, but parent returns null, so final result is null
        assertNull(invokeFindEnclosingAttribute(child, "test"));
    }

    @Test
    public void testFindEnclosingAttribute_NonElementNode() throws Exception {
        // Text Node (not an Element)
        Node textNode = mock(Node.class);
        when(textNode.getNodeType()).thenReturn(Node.TEXT_NODE);

        // Parent Element with attribute
        Element parent = mock(Element.class);
        when(parent.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(parent.getAttribute("test")).thenReturn("val");
        when(textNode.getParentNode()).thenReturn(parent);

        assertEquals("val", invokeFindEnclosingAttribute(textNode, "test"));
    }

    @Test
    public void testFindEnclosingAttribute_NoAttributeFoundInHierarchy() throws Exception {
        Element element = mock(Element.class);
        when(element.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(element.getAttribute("missing")).thenReturn("");
        when(element.getParentNode()).thenReturn(null);

        assertNull(invokeFindEnclosingAttribute(element, "missing"));
    }

    @Test
    public void testFindEnclosingAttribute_DeepHierarchy() throws Exception {
        Element root = mock(Element.class);
        when(root.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(root.getAttribute("key")).thenReturn("rootValue");

        Element middle = mock(Element.class);
        when(middle.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(middle.getAttribute("key")).thenReturn("");
        when(middle.getParentNode()).thenReturn(root);

        Element leaf = mock(Element.class);
        when(leaf.getNodeType()).thenReturn(Node.ELEMENT_NODE);
        when(leaf.getAttribute("key")).thenReturn("");
        when(leaf.getParentNode()).thenReturn(middle);

        assertEquals("rootValue", invokeFindEnclosingAttribute(leaf, "key"));
    }
}
